SELECT wo.*
FROM jsh_work_order wo
WHERE 1=1


    AND wo.work_order_no LIKE #{bindWorkOrderNo}


    AND wo.production_order_id = #{productionOrderId}


    AND wo.work_type = #{workType}


    AND wo.status = #{status}


    AND wo.handler_id = #{handlerId}


    AND wo.create_time >= #{beginTime}


    AND wo.create_time <= #{endTime}


    AND wo.tenant_id = #{tenantId}

AND IFNULL(wo.delete_flag, '0') != '1'
ORDER BY wo.id DESC

    LIMIT #{offset}, #{rows}

SELECT COUNT(1)
FROM jsh_work_order wo
WHERE 1=1


    AND wo.work_order_no LIKE #{bindWorkOrderNo}


    AND wo.production_order_id = #{productionOrderId}


    AND wo.work_type = #{workType}


    AND wo.status = #{status}


    AND wo.handler_id = #{handlerId}


    AND wo.create_time >= #{beginTime}


    AND wo.create_time <= #{endTime}


    AND wo.tenant_id = #{tenantId}

AND IFNULL(wo.delete_flag, '0') != '1'

