mapper.update:
UPDATE jsh_work_order
SET status = #{status},
    update_by = #{updateBy},
    update_time = #{updateTime}
WHERE id = #{id}
AND IFNULL(delete_flag, '0') != '1'

UPDATE jsh_work_order
SET actual_hours = #{actualHours},
    update_by = #{updateBy},
    update_time = #{updateTime}
WHERE id = #{id}
AND IFNULL(delete_flag, '0') != '1'

UPDATE jsh_work_order SET delete_flag = '1', update_time = #{updateTime}, update_by = #{updater} WHERE id IN
#{id}
AND IFNULL(delete_flag, '0') != '1'

mapper.select:
SELECT status, COUNT(1) AS count FROM jsh_work_order WHERE 1=1
AND tenant_id = #{tenantId}
AND IFNULL(delete_flag, '0') != '1' GROUP BY status ORDER BY status

SELECT work_type, COUNT(1) AS count FROM jsh_work_order WHERE 1=1
AND tenant_id = #{tenantId}
AND IFNULL(delete_flag, '0') != '1' GROUP BY work_type ORDER BY work_type

SELECT work_type, COUNT(1) AS count, IFNULL(SUM(cost), 0) AS totalCost, IFNULL(SUM(labor_cost), 0) AS totalLaborCost, IFNULL(SUM(material_cost), 0) AS totalMaterialCost FROM jsh_work_order WHERE 1=1
AND create_time >= #{beginTime}
AND create_time <= #{endTime}
AND tenant_id = #{tenantId}
AND IFNULL(delete_flag, '0') != '1' GROUP BY work_type ORDER BY work_type

SELECT work_type, COUNT(1) AS count, IFNULL(SUM(estimated_hours), 0) AS totalEstimatedHours, IFNULL(SUM(actual_hours), 0) AS totalActualHours FROM jsh_work_order WHERE 1=1
AND create_time >= #{beginTime}
AND create_time <= #{endTime}
AND tenant_id = #{tenantId}
AND IFNULL(delete_flag, '0') != '1' GROUP BY work_type ORDER BY work_type

SELECT handler_id, handler_name, COUNT(1) AS totalCount, SUM(CASE WHEN status = 'COMPLETED' THEN 1 ELSE 0 END) AS completedCount, IFNULL(SUM(actual_hours), 0) AS totalActualHours FROM jsh_work_order WHERE handler_id IS NOT NULL
AND create_time >= #{beginTime}
AND create_time <= #{endTime}
AND tenant_id = #{tenantId}
AND IFNULL(delete_flag, '0') != '1' GROUP BY handler_id, handler_name ORDER BY completedCount DESC, totalActualHours DESC
